111	function tickValuesToNumbers(axis: Axis, values: (number | string | Date)[]) {
112	    const nums = zrUtil.map(values, val => axis.scale.parse(val));
113	    if (axis.type === 'time' && nums.length > 0) {
114	        // Time axis needs duplicate first/last tick (see TimeScale.getTicks())
115	        // The first and last tick/label don't get drawn
116	        nums.sort();
117	        nums.unshift(nums[0]);
118	        nums.push(nums[nums.length - 1]);
119	    }
120	    return nums;
121	}
