123	export function createAxisLabels(axis: Axis, ctx: AxisLabelsComputingContext): {
124	    labels: AxisLabelInfoDetermined[]
125	} {
126	    const custom = axis.getLabelModel().get('customValues');
127	    if (custom) {
128	        const labelFormatter = makeLabelFormatter(axis);
129	        const extent = axis.scale.getExtent();
130	        const tickNumbers = tickValuesToNumbers(axis, custom);
131	        const ticks = zrUtil.filter(tickNumbers, val => val >= extent[0] && val <= extent[1]);
132	        return {
133	            labels: zrUtil.map(ticks, numval => {
134	                const tick = {value: numval};
135	                return {
136	                    formattedLabel: labelFormatter(tick),
137	                    rawLabel: axis.scale.getLabel(tick),
138	                    tickValue: numval,
139	                    time: undefined as ScaleTick['time'] | NullUndefined,
140	                    break: undefined as VisualAxisBreak | NullUndefined,
141	                };
142	            }),
143	        };
144	    }
145	    // Only ordinal scale support tick interval
146	    return axis.type === 'category'
147	        ? makeCategoryLabels(axis, ctx)
148	        : makeRealNumberLabels(axis);
149	}
