151	/**
152	 * @param tickModel For example, can be axisTick, splitLine, splitArea.
153	 */
154	export function createAxisTicks(
155	    axis: Axis,
156	    tickModel: AxisBaseModel,
157	    opt?: Pick<ScaleGetTicksOpt, 'breakTicks' | 'pruneByBreak'>
158	): {
159	    ticks: number[],
160	    tickCategoryInterval?: number
161	} {
162	    const custom = axis.getTickModel().get('customValues');
163	    if (custom) {
164	        const extent = axis.scale.getExtent();
165	        const tickNumbers = tickValuesToNumbers(axis, custom);
166	        return {
167	            ticks: zrUtil.filter(tickNumbers, val => val >= extent[0] && val <= extent[1])
168	        };
169	    }
170	    // Only ordinal scale support tick interval
171	    return axis.type === 'category'
172	        ? makeCategoryTicks(axis, tickModel)
173	        : {ticks: zrUtil.map(axis.scale.getTicks(opt), tick => tick.value)};
174	}
