185	function makeCategoryLabelsActually(
186	    axis: Axis,
187	    labelModel: Model<AxisBaseOption['axisLabel']>,
188	    ctx: AxisLabelsComputingContext
189	): {
190	    labels: AxisLabelInfoDetermined[]
191	    labelCategoryInterval: number
192	} {
193	    const labelsCache = ensureCategoryLabelCache(axis);
194	    const optionLabelInterval = getOptionCategoryInterval(labelModel);
195	    const isEstimate = ctx.kind === AxisTickLabelComputingKind.estimate;
196	
197	    // In AxisTickLabelComputingKind.estimate, the result likely varies during a single
198	    // pass of ec main process,due to the change of axisExtent, and will not be shared with
199	    // splitLine. Therefore no cache is used.
200	    if (!isEstimate) {
201	        // PENDING: check necessary?
202	        const result = axisCacheGet(labelsCache, optionLabelInterval);
203	        if (result) {
204	            return result;
205	        }
206	    }
207	
208	    let labels;
209	    let numericLabelInterval;
210	
211	    if (zrUtil.isFunction(optionLabelInterval)) {
212	        labels = makeLabelsByCustomizedCategoryInterval(axis, optionLabelInterval);
213	    }
214	    else {
215	        numericLabelInterval = optionLabelInterval === 'auto'
216	            ? makeAutoCategoryInterval(axis, ctx) : optionLabelInterval;
217	        labels = makeLabelsByNumericCategoryInterval(axis, numericLabelInterval);
218	    }
219	
220	    const result = {labels, labelCategoryInterval: numericLabelInterval};
221	    if (!isEstimate) {
222	        axisCacheSet(labelsCache, optionLabelInterval, result);
223	    }
224	    else {
225	        ctx.out.noPxChangeTryDetermine.push(function () {
226	            axisCacheSet(labelsCache, optionLabelInterval, result);
227	            return true;
228	        });
229	    }
230	    return result;
231	}
