278	    const ticks = axis.scale.getTicks();
279	    const labelFormatter = makeLabelFormatter(axis);
280	    return {
281	        labels: zrUtil.map(ticks, function (tick, idx) {
282	            return {
283	                formattedLabel: labelFormatter(tick, idx),
284	                rawLabel: axis.scale.getLabel(tick),
285	                tickValue: tick.value,
286	                time: tick.time,
287	                break: tick.break,
288	            };
