293	// Large category data calculation is performance sensitive, and ticks and label probably will
294	// be fetched multiple times (e.g. shared by splitLine and axisTick). So we cache the result.
295	// axis is created each time during a ec process, so we do not need to clear cache.
296	const ensureCategoryTickCache = initAxisCacheMethod('axisTick');
297	const ensureCategoryLabelCache = initAxisCacheMethod('axisLabel');
