310	function axisCacheGet<TKey, TVal>(cache: AxisCache<TKey, TVal>, key: TKey): TVal | NullUndefined {
311	    for (let i = 0; i < cache.list.length; i++) {
312	        if (cache.list[i].key === key) {
313	            return cache.list[i].value;
314	        }
315	    }
316	}
317	
318	function axisCacheSet<TKey, TVal>(cache: AxisCache<TKey, TVal>, key: TKey, value: TVal): TVal {
319	    cache.list.push({key: key, value: value});
320	    return value;
321	}
