205	        const isUTC = this.getSetting('useUTC');
206	        let upperUnitIndex = primaryTimeUnits.length - 1;
207	        let maxLevel = 0;
208	        each(ticks, tick => {
209	            upperUnitIndex = Math.min(upperUnitIndex, indexOf(primaryTimeUnits, tick.time.upperTimeUnit));
210	            maxLevel = Math.max(maxLevel, tick.time.level);
