227	                    indexOf(primaryTimeUnits, getUnitFromValue(trimmedBrk.vmin, isUTC)),
228	                    indexOf(primaryTimeUnits, getUnitFromValue(trimmedBrk.vmax, isUTC)),
229	                );
230	                let upperBrkUnitIndex = 0;
231	                for (let unitIdx = 0; unitIdx < primaryTimeUnits.length; unitIdx++) {
