279	    calcNiceTicks(approxTickNum: number, minInterval: number, maxInterval: number): void {
280	        approxTickNum = approxTickNum || 10;
281	
282	        const span = this._getExtentSpanWithBreaks();
283	        this._approxInterval = span / approxTickNum;
284	
285	        if (minInterval != null && this._approxInterval < minInterval) {
286	            this._approxInterval = minInterval;
287	        }
288	        if (maxInterval != null && this._approxInterval > maxInterval) {
289	            this._approxInterval = maxInterval;
290	        }
291	
292	        const scaleIntervalsLen = scaleIntervals.length;
293	        const idx = Math.min(
294	            bisect(scaleIntervals, this._approxInterval, 0, scaleIntervalsLen),
295	            scaleIntervalsLen - 1
296	        );
297	
298	        // Interval that can be used to calculate ticks
299	        this._interval = scaleIntervals[idx][1];
300	        // Min level used when picking ticks from top down.
301	        // We check one more level to avoid the ticks are to sparse in some case.
302	        this._minLevelUnit = scaleIntervals[Math.max(idx - 1, 0)][0];
303	    }
